// Generated by scripts/gen-plugin.ts — do not edit by hand.
// Source of truth: plugin/zsh/*.zsh (run `npm run gen` after editing).
export const PLUGIN_FILES: Record<string, string> = {
  "accept-line.zsh": "# Scenario 1 — natural language typed at the prompt.\n#\n# Replaces the accept-line widget: instead of handing the line to zsh's parser we\n# can look at it first. Deliberately conservative (PRODUCTION_DESIGN §15): only a\n# line that contains non-ASCII *and* whose first word resolves to nothing is\n# treated as natural language. Everything else goes to `.accept-line` untouched,\n# which also keeps `帮我(找出` out of the PS2 continuation trap.\n\n_ai_shell_should_intercept() {\n  [[ -n ${AI_SHELL_DISABLE-} ]] && return 1\n\n  # Shell syntax can never be natural language — let zsh deal with it.\n  case ${BUFFER[1]} in\n    ''|'#'|'|'|'&'|';'|'('|')'|'<'|'>') return 1 ;;\n  esac\n\n  [[ $BUFFER == *[^[:ascii:]]* ]] || return 1\n\n  local first=$(_ai_shell_first_word \"$BUFFER\")\n  [[ -n $first ]] || return 1\n  whence -w \"$first\" >/dev/null 2>&1 && return 1\n\n  return 0\n}\n\n_ai_shell_accept_line() {\n  if ! _ai_shell_should_intercept; then\n    # Compose: if another plugin owned accept-line, defer to it.\n    if [[ -v widgets[_ai_shell_outer_accept] ]]; then\n      zle _ai_shell_outer_accept\n    else\n      zle .accept-line\n    fi\n    return 0\n  fi\n\n  # Do NOT print the panel here. ZLE's line accounting is stale while a widget\n  # runs, so its redraw after the widget erases the tail of whatever we wrote\n  # (measured at 85 cols: ESC[A×3 + ESC[J wiped `→ cmd`, the footer and the blank\n  # line). Hand the query to precmd, which runs with ZLE inactive — the same\n  # context the command-not-found and non-zero-exit paths print from.\n  typeset -g AI_SHELL_QUERY=$BUFFER\n  BUFFER=\"\"\n  CURSOR=0\n  zle .accept-line\n}\n\n# Keep whatever already owned the widget (`.accept-line` still reaches the\n# builtin, but a plugin's own wrapper would otherwise disappear).\nif [[ -v widgets[accept-line] && ${widgets[accept-line]} != builtin ]]; then\n  zle -A accept-line _ai_shell_outer_accept\nfi\nzle -N accept-line _ai_shell_accept_line\n",
  "ai-shell.zsh": "# AI Shell — zsh integration entry point (zsh 5.9+).\n#\n# Sourced from ~/.zshrc (`ai-shell install`). The plugin only ever *suggests*:\n# the model's command is pasted into ZLE's BUFFER and still needs the user's\n# Enter, so nothing here executes anything the model produced.\n#\n# Hot path rule: a normal command must not fork, network, or shell out. All\n# classification below is builtin-only string work.\n\nif [[ -n ${AI_SHELL_LOADED-} ]]; then\n  return 0\nfi\ntypeset -g AI_SHELL_LOADED=1\n\n# <repo>/plugin/zsh/ai-shell.zsh -> <repo>\ntypeset -g AI_SHELL_ROOT=${${(%):-%x}:A:h:h:h}\n\n# How the runtime is invoked: an explicit binary (AI_SHELL_BIN), one installed on\n# PATH, or — for in-repo development — Node running the TypeScript directly.\ntypeset -ga AI_SHELL_CMD\nif [[ -n ${AI_SHELL_BIN-} ]]; then\n  AI_SHELL_CMD=(\"$AI_SHELL_BIN\")\nelif (( $+commands[ai-shell] )); then\n  AI_SHELL_CMD=(\"${commands[ai-shell]}\")\nelse\n  AI_SHELL_CMD=(node \"$AI_SHELL_ROOT/runtime/main.ts\")\nfi\n\ntypeset -g AI_SHELL_SESSION_DIR=\"${TMPDIR:-/tmp}/ai-shell-${UID}-$$\"\nexport AI_SHELL_SESSION_DIR\n[[ -d $AI_SHELL_SESSION_DIR ]] || mkdir -p -- \"$AI_SHELL_SESSION_DIR\"\n\n# Config (all optional).\ntypeset -g AI_SHELL_MODEL=${AI_SHELL_MODEL-}\ntypeset -g AI_SHELL_TIMEOUT_MS=${AI_SHELL_TIMEOUT_MS-}\ntypeset -g AI_SHELL_LOG=${AI_SHELL_LOG-}\ntypeset -g AI_SHELL_LOG_FILE=${AI_SHELL_LOG_FILE-$AI_SHELL_SESSION_DIR/log}\ntypeset -g AI_SHELL_MAX_EXIT_AI=${AI_SHELL_MAX_EXIT_AI-3}\ntypeset -g AI_SHELL_PLATFORM=$(uname -srm 2>/dev/null)\n\n# $EPOCHREALTIME feeds the latency column of the log; without this module it is\n# empty and every measurement silently recorded 0.\nzmodload zsh/datetime 2>/dev/null\ntypeset -g AI_SHELL_LAST_CMD=\"\"\ntypeset -g AI_SHELL_QUERY=\"\"\ntypeset -gi AI_SHELL_FAIL_STREAK=0\n\n# Commands whose non-zero exit is normal, not a failure to explain.\ntypeset -ga AI_SHELL_IGNORE=(grep egrep fgrep rg ag ack diff cmp test '[' '[[' false)\n\nfor _ai_shell_module in context accept-line cnf lifecycle inject; do\n  source \"$AI_SHELL_ROOT/plugin/zsh/${_ai_shell_module}.zsh\"\ndone\nunset _ai_shell_module\n\nautoload -Uz add-zsh-hook\nadd-zsh-hook preexec _ai_shell_preexec\nadd-zsh-hook precmd _ai_shell_precmd\nadd-zsh-hook zshexit _ai_shell_cleanup\n\n# Shell-side facts for `ai-shell doctor` (the CLI runs this inside an\n# interactive zsh, where ZLE state and the plugin's own widgets are visible).\nai-shell-doctor() {\n  local -a lines\n  lines+=(\"zsh         : $ZSH_VERSION\")\n  if [[ ${widgets[accept-line]-} == user:_ai_shell_accept_line ]]; then\n    lines+=(\"accept-line : ai-shell 已接管\")\n  else\n    lines+=(\"accept-line : ${widgets[accept-line]:-builtin}（不是 ai-shell，可能被别的插件覆盖）\")\n  fi\n  lines+=(\"line-init   : ${widgets[zle-line-init]:-（未注册）}\")\n  lines+=(\"runtime     : ${AI_SHELL_CMD[*]}\")\n  lines+=(\"session dir : $AI_SHELL_SESSION_DIR $([[ -w $AI_SHELL_SESSION_DIR ]] && print -n 可写 || print -n 不可写)\")\n  lines+=(\"comments    : ${options[interactive_comments]}\")\n  print -rl -- \"${lines[@]}\"\n}\n\n# Pick up plugin updates without opening a new terminal (the load guard above\n# would otherwise keep the version this shell started with).\nai-shell-reload() {\n  unset AI_SHELL_LOADED\n  source \"$AI_SHELL_ROOT/plugin/zsh/ai-shell.zsh\"\n}\n",
  "cnf.zsh": "# Scenario 2 — `command not found`.\n#\n# zsh runs this handler in a subshell (measured), so anything assigned here dies\n# with it: no BUFFER writes, no `print -z`. The panel is streamed from the\n# subshell (it inherits the tty) and the suggestion is handed to the parent\n# through the pending file, which zle-line-init injects.\n\ncommand_not_found_handler() {\n  # Keep zsh's own message: users expect to see what failed.\n  print -u2 -- \"zsh: command not found: $1\"\n\n  [[ -o interactive ]] || return 127\n  [[ -n ${AI_SHELL_DISABLE-} ]] && return 127\n\n  # Tell the next precmd that this failure has already been handled (S3).\n  : >| \"$AI_SHELL_SESSION_DIR/cnf-handled\"\n\n  # preexec ran in the parent, so the full original line is inherited here.\n  _ai_shell_ask command_not_found \"${AI_SHELL_LAST_CMD:-${(j: :)@}}\" \"$1\" 127\n\n  return 127\n}\n",
  "context.zsh": "# Context assembly + runtime invocation. This is the only place the shell talks\n# to the Node runtime.\n\n# First whitespace-delimited word of a command line, leading blanks stripped.\n# Shared by the natural-language check and the exit-code ignore list.\n_ai_shell_first_word() {\n  local trimmed=${1##[[:space:]]#}\n  print -r -- \"${trimmed%%[[:space:]]*}\"\n}\n\n# $1=trigger $2=ms $3=exit code $4=command — only written when AI_SHELL_LOG is on\n# (the e2e suite asserts \"normal commands leave no trace\" through this file).\n_ai_shell_log() {\n  [[ -n $AI_SHELL_LOG ]] || return 0\n  print -r -- \"trigger=$1 ms=$2 rc=$3 cmd=$4\" >> \"$AI_SHELL_LOG_FILE\"\n}\n\n# Emits the NUL-separated context on stdout, field order fixed by\n# runtime/context.ts. Values are printed verbatim, so newlines/quotes/control\n# characters need no escaping.\n# $1=trigger $2=buffer $3=last command $4=exit code\n_ai_shell_context() {\n  local -a recent=()\n  # zsh returns an EMPTY slice for ${arr[-20,-1]} when the array is shorter than\n  # 20 — clamp by hand, otherwise short histories silently vanish.\n  local -a keys=(${(on)${(k)history}})\n  (( ${#keys} > 20 )) && keys=(\"${keys[-20,-1]}\")\n  local key\n  for key in \"${keys[@]}\"; do\n    recent+=(\"${history[$key]}\")\n  done\n\n  # A fresh shell's $history is empty (zsh does not preload the history file), so\n  # a failure on the first few commands would otherwise be judged with no context.\n  if (( ${#recent} < 20 )) && [[ -r ${HISTFILE-} ]]; then\n    local -a past=()\n    local line\n    for line in \"${(@f)$(command tail -n 20 -- \"$HISTFILE\" 2>/dev/null)}\"; do\n      [[ $line == ': '*';'* ]] && line=${line#*;}   # tolerate extended history format\n      [[ -n $line ]] && past+=(\"$line\")\n    done\n    recent=(\"${past[@]}\" \"${recent[@]}\")\n    (( ${#recent} > 20 )) && recent=(\"${recent[-20,-1]}\")\n  fi\n\n  local envdump=$(env)\n\n  print -rn -- \"1\"$'\\0'\n  print -rn -- \"zsh\"$'\\0'\n  print -rn -- \"$PWD\"$'\\0'\n  # Strip the \"  # rationale\" the runtime appends to suggestions: fed back as\n  # context it made the model explain its own comment instead of the failure.\n  print -rn -- \"${2%%  \\# *}\"$'\\0'\n  print -rn -- \"${3%%  \\# *}\"$'\\0'\n  print -rn -- \"$4\"$'\\0'\n  print -rn -- \"$1\"$'\\0'\n  print -rn -- \"${(F)recent}\"$'\\0'\n  print -rn -- \"$envdump\"$'\\0'\n  print -rn -- \"$AI_SHELL_SESSION_DIR/pending\"$'\\0'\n  print -rn -- \"$AI_SHELL_PLATFORM\"$'\\0'\n}\n\n# Runs the runtime, which streams the panel to the terminal and writes the\n# suggestion (when there is one) to $AI_SHELL_SESSION_DIR/pending. Always\n# returns 0: a broken AI call must never change the shell's behaviour.\n# $1=trigger $2=buffer $3=last command $4=exit code\n_ai_shell_ask() {\n  local trigger=$1 start=$EPOCHREALTIME\n  local out=$AI_SHELL_SESSION_DIR/pending\n  # zsh does not word-split unquoted expansions, so `${VAR:+--model $VAR}`\n  # would arrive as one mangled argv element. Build a real argv array instead.\n  local -a extra=()\n  [[ -n ${AI_SHELL_MODEL-} ]] && extra+=(--model \"$AI_SHELL_MODEL\")\n  [[ -n ${AI_SHELL_TIMEOUT_MS-} ]] && extra+=(--timeout \"$AI_SHELL_TIMEOUT_MS\")\n  # Trailing `# explanation` is only inert when the shell treats it as a comment;\n  # with interactive_comments off those words become arguments to the command.\n  [[ -o interactive_comments ]] && extra+=(--comment)\n  rm -f -- \"$out\"\n\n  _ai_shell_context \"$@\" | \"${AI_SHELL_CMD[@]}\" ask \"${extra[@]}\"\n  local rc=$?\n\n  local elapsed=$(( (EPOCHREALTIME - start) * 1000 ))\n  _ai_shell_log \"$trigger\" \"${elapsed%.*}\" \"$rc\" \"$2\"\n  return 0\n}\n\n_ai_shell_cleanup() {\n  zmodload zsh/system 2>/dev/null\n  [[ ${sysparams[pid]} == $$ ]] || return 0   # subshell: leave the parent's dir alone\n  rm -rf -- \"$AI_SHELL_SESSION_DIR\"\n}\n",
  "inject.zsh": "# Pending-suggestion injection.\n#\n# zle-line-init runs inside a widget, so writing BUFFER here is legal (unlike\n# from the command-not-found subshell). At line-init the buffer is always empty,\n# so nothing the user typed can be clobbered.\n\n_ai_shell_line_init() {\n  local out=$AI_SHELL_SESSION_DIR/pending\n  [[ -s $out ]] || return 0\n\n  local suggestion=$(<$out)\n  rm -f -- \"$out\"\n  [[ -n $suggestion ]] || return 0\n\n  BUFFER=$suggestion\n  CURSOR=${#BUFFER}\n}\n\n# add-zle-hook-widget chains with other line-init widgets instead of\n# overwriting them (starship, autosuggestions, …).\nautoload -Uz add-zle-hook-widget\nadd-zle-hook-widget line-init _ai_shell_line_init\n",
  "lifecycle.zsh": "# Scenario 3 — a command that ran and failed.\n#\n# precmd runs between the command's output and the next prompt, so a panel\n# printed here lands exactly where the design wants it. Failures that were\n# already handled (command-not-found, an intercepted natural-language line,\n# Ctrl+C) are skipped, as are commands whose non-zero exit is normal.\n\n_ai_shell_preexec() {\n  typeset -g AI_SHELL_LAST_CMD=$1\n}\n\n_ai_shell_precmd() {\n  local ret=$?\n\n  # A natural-language line intercepted by the accept-line widget: answer it here,\n  # where ZLE is not active and the panel survives intact.\n  if [[ -n ${AI_SHELL_QUERY-} ]]; then\n    local query=$AI_SHELL_QUERY\n    AI_SHELL_QUERY=\"\"\n    _ai_shell_ask nl \"$query\" \"\" \"\"\n    return $ret\n  fi\n\n  if [[ -e $AI_SHELL_SESSION_DIR/cnf-handled ]]; then\n    rm -f -- \"$AI_SHELL_SESSION_DIR/cnf-handled\"\n    return $ret\n  fi\n  [[ -n ${AI_SHELL_DISABLE-} ]] && return $ret\n\n  if (( ret == 0 || ret == 130 )); then\n    AI_SHELL_FAIL_STREAK=0\n    return $ret\n  fi\n\n  local cmd=${AI_SHELL_LAST_CMD:-}\n  [[ -n $cmd ]] || return $ret\n\n  local first=$(_ai_shell_first_word \"$cmd\")\n  # Read the extra list at check time so an interactive `export` takes effect too.\n  local -a extra=(${=AI_SHELL_IGNORE_EXTRA-})\n  (( ${AI_SHELL_IGNORE[(I)$first]} + ${extra[(I)$first]} )) && return $ret\n\n  (( AI_SHELL_FAIL_STREAK++ ))\n  (( AI_SHELL_FAIL_STREAK > AI_SHELL_MAX_EXIT_AI )) && return $ret\n\n  _ai_shell_ask non_zero_exit \"$cmd\" \"$cmd\" \"$ret\"\n  return $ret\n}\n",
};
